    #{task.taskId}, #{task.taskKey}, #{task.title}, #{task.description}, #{task.severity}, #{task.incidentId}, #{task.sourceEventId}, #{task.sourceSystem}, #{task.eventStage}, #{task.originSourceSystem}, #{task.targetSystem}, #{task.taskType}, #{task.taskTypeCode}, #{task.status}, #{task.priority}, #{task.tenantId}, #{task.siteId}, #{task.plantId}, #{task.objectType}, #{task.objectId}, #{task.eventType}, #{task.errorCode}, #{task.requestedSkill}, #{task.handoffMode}, #{task.correlationId}, #{task.rootTaskId}, #{task.parentTaskId}, #{task.sourceTaskId}, #{task.requestingTaskId}, #{task.requestingAgentId}, #{task.a2aPolicyId}, #{task.hopCount}, #{task.resultAggregationPolicy}, #{task.childCancellationPolicy}, #{task.childFailurePolicy}, #{task.issueSyncPolicy}, #{task.issueSyncPolicySource}, #{task.issueSyncPolicyInheritanceMode}, #{task.issueSyncPolicyInheritedFromTaskId}, #{task.createdByType}, #{task.createdById}, #{task.originPrincipalType}, #{task.originPrincipalId}, #{task.actorPrincipalType}, #{task.actorPrincipalId}, #{task.originCredentialId}, #{task.originOauthClientId}, #{task.originEventId}, #{task.originWorkloadSourceSystem}, #{task.originCorrelationId}, #{task.initialPriority}, #{task.initialSeverity}, #{task.originDepartmentId}, #{task.originGroupId}, #{task.originOrganizationSource}, #{task.originOrganizationStatus}, #{task.originSourceIp}, #{task.originApiResource}, #{task.authorizationDecisionId}, #{task.securityGlobalEpoch}, #{task.securityTenantEpoch}, #{task.securityPrincipalEpoch}, #{task.requestId}, #{task.traceId}, #{task.authenticationMethod}, #{task.workloadPurpose}, #{task.synthetic}, #{task.provenanceCapturedAt}, #{task.version}, #{task.creationIdempotencyKey}, #{task.ownerDepartmentId}, #{task.ownerGroupId}, #{task.originScopeStatus}, #{task.originScopeSourceVersion}, #{task.originScopeInheritedAt}, #{task.requesterDepartmentId}, #{task.requesterGroupId}, #{task.requesterDomainId}, #{task.executorDepartmentId}, #{task.executorGroupId}, #{task.executorDomainId}, #{task.visibilityPolicy}, #{task.sensitivityLevel}, #{task.matchedFlowId}, #{task.matchedRuleId}, #{task.assignedPoolId}, #{task.targetPoolId}, #{task.classificationStatus}, coalesce(coalesce(cast(#{task.classificationResultJson} as jsonb), '{}'::jsonb), '{}'::jsonb), #{task.routingPath}, #{task.routingPolicy}, coalesce(coalesce(cast(#{task.requiredCapabilitiesJson} as jsonb), '[]'::jsonb), '[]'::jsonb), #{task.createdReason}, #{task.occurrenceCountAtCreation}, #{task.createdAt}, #{task.updatedAt}, #{task.timeoutAt}, #{task.terminalAt}, #{task.reassignmentCount}, #{task.nextDispatchAttemptAt}, #{task.dispatchAttemptCount}, #{task.dispatchRetryReason}, #{task.dispatchRecoveryClaimedBy}, #{task.dispatchRecoveryClaimUntil}, #{task.lifecycleReason}, #{task.failureDomain}, #{task.failureCode}, #{task.failureAt}, #{task.externalExecutionKey}
