mapper.select:
select * from tasks
where task_lifecycle <> 'CLOSED' and updated_at < #{cutoff}
order by updated_at asc limit #{limit}

select * from tasks
where status = #{status} and updated_at < #{cutoff}
order by updated_at asc limit #{limit}

mapper.update:
update tasks set
    dispatch_recovery_claimed_by = null,
    dispatch_recovery_claim_until = null,
    updated_at = #{now}
where task_id = #{taskId}
  and dispatch_recovery_claimed_by = #{workerId}
  and dispatch_recovery_claim_until = #{claimUntil}

update tasks set
    status = #{newStatus},
    timeout_at = #{timeoutAt},
    terminal_at = #{terminalAt},
    updated_at = #{updatedAt},
    lifecycle_reason = #{lifecycleReason}
where task_id = #{taskId}
  and status in

      #{status}

mapper.select:
select t.* from tasks t
where t.tenant_id = #{tenantId}
and t.incident_id = #{incidentId}
and t.site_id = #{siteId}
and t.plant_id = #{plantId}
and t.task_type = #{taskType}
and t.status = #{status}

    and (t.created_at < #{beforeCreatedAt} or (t.created_at = #{beforeCreatedAt} and t.task_id < #{beforeTaskId}))


    and 1 = 0




        and (

                t.task_id in
                #{id}
                or


                t.owner_department_id in #{id}
                or t.requester_department_id in #{id}
                or t.executor_department_id in #{id}
                or


                exists (select 1 from org_department_closure dc where dc.tenant_id=t.tenant_id
                    and dc.ancestor_department_id in #{id}
                    and dc.descendant_department_id in (t.owner_department_id,t.requester_department_id,t.executor_department_id))
                or


                t.owner_group_id in #{id}
                or t.requester_group_id in #{id}
                or t.executor_group_id in #{id}
                or

            exists (select 1 from resource_participants rp where rp.tenant_id=t.tenant_id
                and rp.resource_type='TASK' and rp.resource_id=t.task_id and rp.participant_status='ACTIVE'
                and current_timestamp >= rp.valid_from and (rp.valid_to is null or current_timestamp < rp.valid_to)
                and ((rp.participant_type='USER' and rp.participant_ref_id=#{plan.principalId})

                  or (rp.participant_type='DEPARTMENT' and rp.participant_ref_id in #{id})


                  or (rp.participant_type='GROUP' and rp.participant_ref_id in #{id})

                ))
        )



    and t.task_id not in #{id}


    and coalesce(t.owner_department_id,'') not in #{id}
    and coalesce(t.requester_department_id,'') not in #{id}
    and coalesce(t.executor_department_id,'') not in #{id}


    and not exists (select 1 from org_department_closure dd where dd.tenant_id=t.tenant_id
        and dd.ancestor_department_id in #{id}
        and dd.descendant_department_id in (t.owner_department_id,t.requester_department_id,t.executor_department_id))


    and coalesce(t.owner_group_id,'') not in #{id}
    and coalesce(t.requester_group_id,'') not in #{id}
    and coalesce(t.executor_group_id,'') not in #{id}


and not exists (
    select 1 from resource_scope_denies rd
    where rd.tenant_id=t.tenant_id
      and rd.resource_type='TASK'
      and rd.deny_state='ACTIVE'
      and rd.valid_from <= current_timestamp
      and (rd.valid_to is null or rd.valid_to > current_timestamp)
      and (rd.permission_code is null or rd.permission_code='' or rd.permission_code=#{plan.permissionCode})
      and (
            (rd.principal_type=#{plan.principalType} and rd.principal_id=#{plan.principalId})

            or (rd.principal_type='DEPARTMENT' and rd.principal_id in
                #{id})


            or (rd.principal_type='GROUP' and rd.principal_id in
                #{id})

      )
      and (
            rd.scope_type='TENANT'
            or (rd.scope_type='RESOURCE' and rd.scope_ref_id=t.task_id)
            or (rd.scope_type='TASK_CHAIN' and rd.scope_ref_id in (t.task_id,t.root_task_id))
            or (rd.scope_type='DEPARTMENT' and rd.scope_ref_id in
                (t.owner_department_id,t.requester_department_id,t.executor_department_id))
            or (rd.scope_type='DEPARTMENT_SUBTREE' and exists (
                select 1 from org_department_closure rdc
                where rdc.tenant_id=t.tenant_id
                  and rdc.ancestor_department_id=rd.scope_ref_id
                  and rdc.descendant_department_id in
                      (t.owner_department_id,t.requester_department_id,t.executor_department_id)))
            or (rd.scope_type='GROUP' and rd.scope_ref_id in
                (t.owner_group_id,t.requester_group_id,t.executor_group_id))
            or (rd.scope_type='OWNER' and (
                (rd.principal_type='DEPARTMENT' and rd.principal_id=t.owner_department_id)
                or (rd.principal_type='GROUP' and rd.principal_id=t.owner_group_id)))
            or (rd.scope_type='PARTICIPANT' and exists (
                select 1 from resource_participants drp
                where drp.tenant_id=t.tenant_id and drp.resource_type='TASK'
                  and drp.resource_id=t.task_id and drp.participant_status='ACTIVE'
                  and drp.valid_from <= current_timestamp
                  and (drp.valid_to is null or drp.valid_to > current_timestamp)
                  and drp.participant_type=rd.principal_type
                  and drp.participant_ref_id=rd.principal_id))
      )
)
order by t.created_at desc, t.task_id desc limit #{limit}

